p="index.html";s=open(p,encoding="utf-8").read()
def rep(o,n,k=1):
    global s;c=s.count(o);assert c==k,(o[:70],c);s=s.replace(o,n)
# Page du bonus et placement du collatéral : l'essentiel visible, le calcul replié
a="""Le minimum suit les salaires : leurs points de base du trimestre, ÷ 2,5 pour le front office et ÷ 10 pour le back office, en % de la commission (${dec(bonBase()*100,1)} % avec votre équipe, soit ${mm(bonBase()*pf)}) ; chaque cran le multiplie par 1,25, 1,5, 2, 2,5 ou 4 — le dernier est hors de prix — sans jamais dépasser 90 % de la commission. Le moral du desk (${Math.round(motV())} aujourd'hui) fait chaque trimestre la moitié du chemin vers la cible de votre cran (${MORAL.tg.join(', ')}, plus selon vos locaux), pourvu qu'un bonus soit versé ; sinon, vers ${MORAL.tg[0]}. À 50, tout est neutre ; au-dessus, les avantages s'envolent jusqu'à 100, et une baisse de taux coûte 5 points par cran. Le moral fixe cinq choses : un multiplicateur sur vos coûts d'impact de marché (ni la demi-fourchette ni le courtage), la précision de la lecture des dépêches et de la veille des extrêmes, les chances de gagner des anecdotes du desk, le sang-froid (fréquence des accidents internes et des fuites, gravité des accidents et des crises, ×1,4 à 0, ×0,7 à 100) et le risque de débauchage. Sous 20, le desk peut partir en groupe ; au-dessus de 80, il peut refuser toutes les offres.</p>"""
b="""Le minimum suit vos salaires : ${dec(bonBase()*100,1)} % avec votre équipe, soit ${mm(bonBase()*pf)}. Chaque cran le multiplie, jusqu'au 🔥, hors de prix. Plus le cran est haut, plus le moral du desk (${Math.round(motV())} aujourd'hui) monte — pourvu qu'il y ait un bonus à verser.</p>
  <details style="margin:0 0 8px"><summary>Le calcul et les effets du moral</summary><p class="note">Minimum : les points de base de salaires du trimestre, ÷ 2,5 pour le front office et ÷ 10 pour le back office, en % de la commission. Crans : ×1, 1,25, 1,5, 2, 2,5 et 4, sans jamais dépasser 90 % de la commission. Le moral fait chaque trimestre la moitié du chemin vers la cible de votre cran (${MORAL.tg.join(', ')}, plus selon vos locaux) si un bonus est versé, sinon vers ${MORAL.tg[0]} ; baisser d'un cran coûte ${MORAL.cut} points par cran.</p><p class="note">À 50, tout est neutre. Le moral règle l'impact de vos ordres, la lecture des dépêches et la veille des extrêmes, les chances des anecdotes, le sang-froid (accidents, fuites et gravité des crises) et le débauchage. Sous ${MORAL.lo}, le desk peut partir en groupe ; au-dessus de ${MORAL.hi}, il peut refuser toutes les offres.</p></details>"""
rep(a,b)
rep(""" · moral → ${Math.round(m)} · coûts ×${dec(motC(m),2)} · lecture ×""",""" · moral → ${Math.round(m)} · impact ×${dec(motC(m),2)} · lecture ×""")
rep("""<p class="note" style="margin-top:6px">${colOpt().d} Le surcroît de chaque placement change d'un trimestre à l'autre ; en moyenne, plus le risque est grand, plus l'attendu l'est. Les défauts tombent ${dec(COLK,1)} fois plus souvent le trimestre d'un événement extrême (et d'autant moins sinon) : le rendement paie le drain de volatilité et cette corrélation avec votre book.</p>""",
    """<p class="note" style="margin-top:6px">${colOpt().d} En moyenne, plus le risque est grand, plus l'attendu l'est.</p><details><summary>Défauts et extrêmes</summary><p class="note">Le surcroît de chaque placement change d'un trimestre à l'autre. Les défauts tombent ${dec(COLK,1)} fois plus souvent le trimestre d'un événement extrême (et d'autant moins sinon) : le rendement paie le drain de volatilité et cette corrélation avec votre book.</p></details>""")
open(p,"w",encoding="utf-8").write(s)
